// Разбираем callback_query
const item = $input.first().json;
const callbackQuery = item.callback_query;

// Защита от обычных сообщений (без callback)
if (!callbackQuery) {
  return [{
    json: {
      action: 'none',
      channelId: '',
      chatId: String(item.message?.chat?.id || ''),
      callbackQueryId: '',
      messageId: '',
      callbackData: '',
      extraData: {}
    }
  }];
}

const callbackData = callbackQuery.data || '';
const chatId = String(callbackQuery.message.chat.id);
const callbackQueryId = callbackQuery.id;
const messageId = callbackQuery.message.message_id;

let action = '';
let channelId = '';
let extraData = {};

if (callbackData.startsWith('approve_')) {
  action = 'approve';
  channelId = callbackData.replace('approve_', '');
} else if (callbackData.startsWith('reject_')) {
  action = 'reject';
  channelId = callbackData.replace('reject_', '');
} else if (callbackData === 'start_parse') {
  action = 'start_parse';
} else if (callbackData === 'confirm_send') {
  action = 'confirm_send';
} else if (callbackData === 'execute_send') {
  action = 'execute_send';
} else if (callbackData === 'cancel_send') {
  action = 'cancel_send';
} else if (callbackData === 'cancel_search') {
  action = 'cancel_search';
} else if (callbackData.startsWith('days_')) {
  action = 'days_selected';
  extraData.days = callbackData.replace('days_', '');
} else {
  action = 'unknown';
}

return [{
  json: {
    action,
    channelId,
    chatId,
    callbackQueryId,
    messageId,
    callbackData,
    extraData
  }
}];

const item = $input.first().json;
const chatId = String(item.chatId);   // уже приходит из "Разобрать callback"

const staticData = $getWorkflowStaticData('global');
if (!staticData.users) staticData.users = {};
if (!staticData.users[chatId]) staticData.users[chatId] = {};

// ставим ожидание дней
staticData.users[chatId].state = 'await_days';
staticData.users[chatId].days_back = null;

return [{ json: { chatId } }];

const item = $input.first().json;
const chatId = item.chatId;
const days = item.extraData.days;
const staticData = $getWorkflowStaticData('global');
if (!staticData.users) staticData.users = {};
if (!staticData.users[chatId]) staticData.users[chatId] = {};
staticData.users[chatId].state = 'waiting_keywords';
staticData.users[chatId].days_back = days;
return [{ json: { chatId, days, callbackQueryId: item.callbackQueryId } }];

const item = $input.first().json;
const message = item.message || {};
const text = (message.text || '').trim();
const chatId = String(message.chat?.id || '');

const staticData = $getWorkflowStaticData('global');
if (!staticData.users) staticData.users = {};
if (!staticData.users[chatId]) staticData.users[chatId] = {};

const currentState = staticData.users[chatId].state || null;

let action = 'default_reply';

// FIX: Check states FIRST before generic niche_input routing
if (currentState === 'await_days') {
  // Will be routed by currentState check (rule await_days) in Роутер состояний
  action = 'default_reply';
} else if (currentState === 'waiting_keywords') {
  action = 'keywords_input';
} else if (text === '/start') {
  action = 'start';
} else if (text && !text.startsWith('/')) {
  action = 'niche_input';
}

return [{
  json: {
    action,
    chatId,
    text,
    payload: {},
    currentState
  }
}];

const item = $input.first().json;
const chatId = item.chatId;
const niche = item.text; // FIX: was item.payload.niche which is always undefined
return [{ json: { chatId, niche, action: 'search_channels' } }];

const searchResult = $input.first().json;
const channels = searchResult.channels || [];
const chatId = $('Подготовить нишу').first().json.chatId;
const niche = $('Подготовить нишу').first().json.niche;
const staticData = $getWorkflowStaticData('global');
if (!staticData.users) staticData.users = {};
if (!staticData.users[chatId]) staticData.users[chatId] = {};
staticData.users[chatId].found_channels = channels;
staticData.users[chatId].current_niche = niche;
return [{ json: { chatId, niche, channels, count: channels.length } }];

const item = $('Обработать результат поиска').first().json;
const channels = item.channels || [];
const niche = item.niche;
const rows = channels.map(ch => ({
  channel_id: ch.id || ch.channel_id || '',
  username: ch.username || '',
  title: ch.title || '',
  description: ch.description || '',
  members_count: ch.members_count || 0,
  niche: niche,
  status: 'pending',
  added_date: new Date().toISOString().split('T')[0]
}));
return rows.map(r => ({ json: r }));

const item = $input.first().json;
const niche = item.niche;
const chatId = item.chatId;
const ai_keywords = [niche];
const lead_signals = ['куплю', 'ищу', 'нужен', 'порекомендуйте', 'помогите найти'];
return [{ json: { niche, chatId, ai_keywords, lead_signals, date_added: new Date().toISOString().split('T')[0] } }];

const item = $input.first().json;
const chatId = item.chatId;
const payload = item.payload || {};
const staticData = $getWorkflowStaticData('global');
const userState = staticData.users && staticData.users[chatId] ? staticData.users[chatId] : {};
const daysBack = item.days_back || payload.days_back || parseInt(userState.days_back || '7');
const keywords = item.keywords || payload.keywords || userState.keywords || [];
if (staticData.users && staticData.users[chatId]) {
  staticData.users[chatId].state = 'idle';
  staticData.users[chatId].days_back = null;
  staticData.users[chatId].keywords = null;
}
return [{ json: { chatId, days_back: daysBack, keywords } }];

const item = $input.first().json;
const chatId = String(item.chatId);
const text = String(item.text || '').trim();

const staticData = $getWorkflowStaticData('global');
if (!staticData.users) staticData.users = {};
if (!staticData.users[chatId]) staticData.users[chatId] = {};

const days = parseInt(text, 10);

if (isNaN(days) || days < 1 || days > 30) {
  return [{ json: { action: 'days_invalid', chatId } }];
}

staticData.users[chatId].days_back = days;
staticData.users[chatId].state = null;

return [{ json: { action: 'days_ok', chatId, days } }];

